NSImage* cocoaImage(const mu::assets::Image& image){
 NSData* bytes=[NSData dataWithBytes:image.rgba.data() length:image.rgba.size()];auto provider=CGDataProviderCreateWithCFData((__bridge CFDataRef)bytes);auto color=CGColorSpaceCreateDeviceRGB();
 auto cg=CGImageCreate(image.width,image.height,8,32,image.width*4,color,kCGImageAlphaLast|kCGBitmapByteOrder32Big,provider,nullptr,YES,kCGRenderingIntentDefault);CGColorSpaceRelease(color);CGDataProviderRelease(provider);
 if(!cg)throw std::runtime_error("Could not create terrain image");NSImage* out=[[NSImage alloc] initWithCGImage:cg size:NSMakeSize(image.width,image.height)];CGImageRelease(cg);return out;
}
SCNGeometry* geometry(const std::vector<SCNVector3>& positions,const std::vector<CGPoint>& uv,const std::vector<std::uint32_t>& indices){
 auto v=[SCNGeometrySource geometrySourceWithVertices:positions.data() count:positions.size()];
 auto t=[SCNGeometrySource geometrySourceWithTextureCoordinates:uv.data() count:uv.size()];NSData* faces=[NSData dataWithBytes:indices.data() length:indices.size()*sizeof(std::uint32_t)];
 auto e=[SCNGeometryElement geometryElementWithData:faces primitiveType:SCNGeometryPrimitiveTypeTriangles primitiveCount:indices.size()/3 bytesPerIndex:4];return [SCNGeometry geometryWithSources:@[v,t] elements:@[e]];
}
