namespace mu::viewer {
void verify_geometry_contract(){
 // Check intermediate quaternion poses, where mesh interpolation used to shrink
 // limbs. SceneKit must keep the basis orthonormal even across a large rotation.
 auto joint=[SCNNode node];auto start=simd_quaternion(0.f,simd_make_float3(0,0,1));auto end=simd_quaternion(float(M_PI*.95),simd_normalize(simd_make_float3(1,2,3)));
 for(unsigned sample=0;sample<=20;sample++){auto q=simd_slerp(start,end,float(sample)/20);joint.simdOrientation=q;auto m=joint.simdTransform;
  for(unsigned c=0;c<3;c++){auto axis=simd_make_float3(m.columns[c].x,m.columns[c].y,m.columns[c].z);if(std::abs(simd_length(axis)-1.f)>1e-5)throw std::runtime_error("Interpolated joint scaled its rigid geometry");
   for(unsigned other=0;other<c;other++){auto b=simd_make_float3(m.columns[other].x,m.columns[other].y,m.columns[other].z);if(std::abs(simd_dot(axis,b))>1e-5)throw std::runtime_error("Interpolated joint sheared its rigid geometry");}
  }
 }
 auto geom=geometry({SCNVector3Make(135,2,-124),SCNVector3Make(136,3,-124),SCNVector3Make(135,2,-125)},{CGPointMake(0,0),CGPointMake(1,0),CGPointMake(0,1)},{0,1,2});
 auto source=[geom geometrySourcesForSemantic:SCNGeometrySourceSemanticVertex].firstObject;
 if(!source||source.vectorCount!=3||source.componentsPerVector!=3||!source.floatComponents)throw std::runtime_error("Renderer vertex source contract failed");
 const float expected[3][3]={{135,2,-124},{136,3,-124},{135,2,-125}};
 auto bytes=reinterpret_cast<const std::uint8_t*>(source.data.bytes);
 for(unsigned i=0;i<3;i++)for(unsigned c=0;c<3;c++){
  auto offset=source.dataOffset+i*source.dataStride+c*source.bytesPerComponent;
  if(offset+source.bytesPerComponent>source.data.length)throw std::runtime_error("Renderer vertex layout exceeds data");
  double value=0;if(source.bytesPerComponent==4){float v;std::memcpy(&v,bytes+offset,4);value=v;}else if(source.bytesPerComponent==8)std::memcpy(&value,bytes+offset,8);else throw std::runtime_error("Unsupported renderer vertex precision");
  if(std::abs(value-expected[i][c])>1e-6)throw std::runtime_error("macOS CGFloat vertex conversion corrupted coordinates");
 }
}
