static NSArray<SCNNode*>* playerMeshes(const std::vector<mu::viewer::Part>& parts,NSArray<SCNNode*>* joints,SCNNode* rig,const std::filesystem::path& data){
 std::vector<SCNVector3> positions,normals;std::vector<CGPoint> uv;std::vector<uint32_t> indices;NSMutableArray<NSValue*>* inverse=[NSMutableArray array];for(unsigned i=0;i<joints.count;i++)[inverse addObject:[NSValue valueWithSCNMatrix4:SCNMatrix4Identity]];
 NSMutableDictionary<NSString*,NSImage*>* textureCache=[NSMutableDictionary dictionary];
 NSMutableArray<SCNNode*>* result=[NSMutableArray array];
 for(auto& part:parts){positions.clear();normals.clear();uv.clear();indices.clear();std::vector<uint16_t> binding;std::vector<float> weights;
  for(auto& face:part.mesh.faces)for(unsigned i=0;i<3;i++){const auto& vertex=part.mesh.vertices.at(face.vertex[i]);auto v=vertex.position;positions.push_back(SCNVector3Make(v.x,v.y,v.z));auto t=part.mesh.uv.at(face.uv[i]);uv.push_back(CGPointMake(t[0],1-t[1]));auto n=part.mesh.normals.at(face.normal[i]).position;normals.push_back(SCNVector3Make(n.x,n.y,n.z));indices.push_back(indices.size());binding.push_back(vertex.bone);weights.push_back(1.f);}
  auto base=geometry(positions,uv,indices);auto model=[SCNGeometry geometryWithSources:[base.geometrySources arrayByAddingObject:[SCNGeometrySource geometrySourceWithNormals:normals.data() count:normals.size()]] elements:base.geometryElements];auto skin=[SCNMaterial material];NSString* textureKey=[NSString stringWithUTF8String:part.mesh.texture.c_str()];NSImage* skinImage=textureCache[textureKey];if(!skinImage){skinImage=cocoaImage(*part.image);textureCache[textureKey]=skinImage;}skin.diffuse.contents=skinImage;skin.lightingModelName=SCNLightingModelConstant;skin.doubleSided=YES;model.materials=@[skin];auto node=[SCNNode nodeWithGeometry:model];node.renderingOrder=2;
  auto weightSource=[SCNGeometrySource geometrySourceWithData:[NSData dataWithBytes:weights.data() length:weights.size()*sizeof(float)] semantic:SCNGeometrySourceSemanticBoneWeights vectorCount:weights.size() floatComponents:YES componentsPerVector:1 bytesPerComponent:sizeof(float) dataOffset:0 dataStride:sizeof(float)];
  auto indexSource=[SCNGeometrySource geometrySourceWithData:[NSData dataWithBytes:binding.data() length:binding.size()*sizeof(uint16_t)] semantic:SCNGeometrySourceSemanticBoneIndices vectorCount:binding.size() floatComponents:NO componentsPerVector:1 bytesPerComponent:sizeof(uint16_t) dataOffset:0 dataStride:sizeof(uint16_t)];
  node.skinner=[SCNSkinner skinnerWithBaseGeometry:model bones:joints boneInverseBindTransforms:inverse boneWeights:weightSource boneIndices:indexSource];node.skinner.skeleton=rig;if(part.equipment){mu::viewer::apply_item_upgrade(node,model,skin,data,*part.equipment);for(SCNNode* overlay in node.childNodes){overlay.skinner=[SCNSkinner skinnerWithBaseGeometry:overlay.geometry bones:joints boneInverseBindTransforms:inverse boneWeights:weightSource boneIndices:indexSource];overlay.skinner.skeleton=rig;}}[result addObject:node];
 }
 return result;
}
static void configureSpiritDark(SCNMaterial* material){material.lightingModelName=SCNLightingModelConstant;material.blendMode=SCNBlendModeMultiply;material.writesToDepthBuffer=NO;material.doubleSided=YES;material.shaderModifiers=@{SCNShaderModifierEntryPointFragment:@"#pragma arguments\nfloat spiritLight;\n#pragma body\n_output.color.rgb = float3(1.0) - clamp(_output.color.rgb * spiritLight, 0.0, 1.0);"};[material setValue:@(4.9) forKey:@"spiritLight"];}
