std::shared_ptr<const mu::viewer::EquipmentAnimation> prepareEquipmentAnimation(const mu::viewer::CharacterBody& body){auto result=std::make_shared<mu::viewer::EquipmentAnimation>();result->periods=body.combatPeriods;result->actions=body.combatActions;for(unsigned clip=0;clip<6;clip++)for(const auto& frame:body.combat[clip]){std::vector<mu::viewer::JointPose> sample;for(unsigned i=0;i<frame.size();i++){auto r=frame[i].rotation,p=frame[i].position;if(frame[i].parent<0){p.x=body.idle.front()[i].position.x;p.y=body.idle.front()[i].position.y;}auto q=simd_mul(simd_quaternion(r.z,simd_make_float3(0,0,1)),simd_mul(simd_quaternion(r.y,simd_make_float3(0,1,0)),simd_quaternion(r.x,simd_make_float3(1,0,0))));sample.push_back({simd_make_float3(p.x,p.y,p.z),simd_normalize(q)});}result->samples[clip].push_back(std::move(sample));}return result;}
NSArray<SCNNode*>* attachmentNodes(const mu::viewer::CharacterBody& body,NSArray<MuCharacterRig*>* __strong* outRigs){NSMutableArray<SCNNode*>* nodes=[NSMutableArray array];NSMutableArray<MuCharacterRig*>* rigs=[NSMutableArray array];for(const auto& attachment:body.attachments){auto animated=[[MuCharacterRig alloc] initWithVisual:attachment.visual];auto grip=[MuEquipmentGrip node];grip.name=[NSString stringWithFormat:@"worn:%u",attachment.slot];grip.slot=attachment.slot;grip.index=attachment.item.index;[grip addChildNode:animated.node];[animated advance:0];[rigs addObject:animated];[nodes addObject:grip];}*outRigs=rigs;return nodes;}
// RenderLinkObject(Link=true): back-only grip and left-hand correction.
void placeAttachments(NSArray<SCNNode*>* nodes,NSArray<SCNNode*>* joints,SCNNode* rig,const std::vector<simd_float4x4>& matrices,bool safe){for(SCNNode* node in nodes)if([node isKindOfClass:MuEquipmentGrip.class]){auto grip=(MuEquipmentGrip*)node;unsigned bone=mu::viewer::equipment_attachment_bone(grip.slot,grip.index,safe);if(bone>=joints.count)continue;if(node.parentNode!=joints[bone])[joints[bone] addChildNode:node];node.simdTransform=mu::viewer::equipment_attachment_transform(grip.slot,grip.index,safe);}}
}
