- (void)correctX:(unsigned)x y:(unsigned)y direction:(unsigned)d{std::lock_guard<std::mutex> lock(movementMutex);motion=mu::viewer::MotionTrack({double(x),sceneData->assets->terrain.height(x,y),-double(y),(double(d)-1)*M_PI/4});motion.setMovementRate(sceneData->movementRate);tileX=x;tileY=y;}
- (BOOL)pathNearEnd{std::lock_guard<std::mutex> lock(movementMutex);return motion.pending()&&motion.remainingDistance()<.35;}
- (std::pair<unsigned,unsigned>)movementEndpoint{std::lock_guard<std::mutex> lock(movementMutex);return {tileX,tileY};}
- (BOOL)pathPending{std::lock_guard<std::mutex> lock(movementMutex);return motion.pending();}
- (std::pair<unsigned,unsigned>)movementTile{std::lock_guard<std::mutex> lock(movementMutex);auto p=motion.position();return {unsigned(std::clamp(int(std::round(p.x)),0,255)),unsigned(std::clamp(int(std::round(-p.z)),0,255))};}
- (void)confirmedPathX:(unsigned)x y:(unsigned)y directions:(const std::vector<unsigned>&)directions{
 unsigned oldX=tileX,oldY=tileY;constexpr int dx[8]={-1,0,1,1,1,0,-1,-1},dy[8]={-1,-1,-1,0,1,1,1,0};std::lock_guard<std::mutex> lock(movementMutex);if(x!=tileX||y!=tileY||!motion.pending())motion.clearPath();
 for(auto d:directions){x+=dx[d];y+=dy[d];motion.enqueue({double(x),sceneData->assets->terrain.height(x,y),-double(y),(double(d)-1)*M_PI/4});}tileX=x;tileY=y;cameraHome.x+=int(x)-int(oldX);cameraHome.z-=int(y)-int(oldY);cameraTarget=SCNVector3Make(x+.5,sceneData->assets->terrain.heightAt(x+.5,y+.5)+.8,-float(y)-.5);
 self.window.title=[NSString stringWithFormat:@"MU EX603 · %@ · online X=%u Y=%u",[NSString stringWithUTF8String:sceneData->mapName.c_str()],x,y];
}
- (void)stopInput{((MuSceneView*)self.sceneView).heldDirection=-1;}
- (NSInteger)heldDirection{return [(MuSceneView*)self.sceneView heldDirection];}
- (void)setMessage:(NSString*)message{self.infoLabel.stringValue=message;}
- (void)updateX:(unsigned)x y:(unsigned)y direction:(unsigned)direction{
 if(x>=256||y>=256||!sceneData)return;
 if(x==tileX&&y==tileY)return;
 float dx=float(int(x)-int(tileX)),dz=-float(int(y)-int(tileY));tileX=x;tileY=y;
 {std::lock_guard<std::mutex> lock(movementMutex);if([self heldDirection]<0)motion.face((double(direction)-1)*M_PI/4);motion.enqueue({double(x),sceneData->assets->terrain.height(x,y),-double(y),(double(direction)-1)*M_PI/4});}
 cameraHome.x+=dx;cameraHome.z+=dz;cameraTarget=SCNVector3Make(x+.5,sceneData->assets->terrain.heightAt(x+.5,y+.5)+.8,-float(y)-.5);
 self.window.title=[NSString stringWithFormat:@"MU EX603 · %@ · online X=%u Y=%u",[NSString stringWithUTF8String:sceneData->mapName.c_str()],x,y];
}
- (unsigned)equipmentRevision{return equipmentApplied.load();}
- (unsigned)playerAction{if(activeClip>=3&&equipmentAnimation)return equipmentAnimation->actions[activeClip];unsigned clip=std::min(activeClip,2u);if(combatStance&&equipmentAnimation)return equipmentAnimation->actions[clip];const auto& r=sceneData->assets->characterResources;return clip==0?r.idle:clip==1?r.walk:r.run;}
- (void)updateEquipment:(std::shared_ptr<const mu::viewer::CharacterBody>)body{
 if(!body||body->bones.size()!=skeletonNodes.count)throw std::runtime_error("Equipment skeleton size differs from active player");for(unsigned i=0;i<body->bones.size();i++){const auto& original=sceneData->assets->idlePoses.front()[i];if(body->bones[i].name!=original.name||body->bones[i].parent!=original.parent)throw std::runtime_error("Equipment skeleton binding differs from active player");}
 std::vector<mu::viewer::Part> parts;for(const auto& mesh:body->meshes)parts.push_back({mesh.mesh,mesh.image,mesh.part==4,mesh.equipment});auto armorNodes=playerMeshes(parts,skeletonNodes,rigNode,sceneData->assets->dataDirectory);auto animation=prepareEquipmentAnimation(*body);NSArray<MuCharacterRig*>* rigs;auto nodes=[armorNodes arrayByAddingObjectsFromArray:attachmentNodes(*body,&rigs)];unsigned generation=++equipmentGeneration;auto view=self.sceneView;__weak MuWorldViewer* weak=self;[view prepareObjects:nodes withCompletionHandler:^(BOOL ready){dispatch_async(dispatch_get_main_queue(),^{MuWorldViewer* owner=weak;if(!owner||owner.sceneView!=view||!owner.sceneView.delegate||owner->equipmentGeneration!=generation)return;if(!ready){[owner setMessage:@"Equipment GPU preparation failed"];return;}std::lock_guard<std::mutex> guard(owner->equipmentMutex);owner->pendingEquipmentGeneration=generation;owner->pendingEquipment=body;owner->pendingEquipmentNodes=nodes;owner->pendingEquipmentRigs=rigs;owner->pendingEquipmentAnimation=animation;});}];
}
- (void)setInterfaceColumns:(unsigned)columns{
 interfaceColumns=std::min(columns,2u);auto bounds=self.window.contentView.bounds;CGFloat width=std::max(1.,bounds.size.width),height=std::max(1.,bounds.size.height);self.interfaceView.frame=NSMakeRect(0,0,width,height);self.sceneView.frame=NSMakeRect(0,0,width,height);
 auto original=[SCNCamera camera];original.fieldOfView=self.cameraNode.camera.fieldOfView;original.zNear=self.cameraNode.camera.zNear;original.zFar=self.cameraNode.camera.zFar;auto projection=[original projectionTransformWithViewportSize:CGSizeMake(width,height)];// Inventory/Warehouse overlay the world; opening panels must not shift its projection.
 [SCNTransaction begin];[SCNTransaction setDisableActions:YES];if(!SCNMatrix4EqualToMatrix4(self.cameraNode.camera.projectionTransform,projection))self.cameraNode.camera.projectionTransform=projection;[SCNTransaction commit];if(!interfaceColumns)[self.window makeFirstResponder:self.sceneView];
}
- (void)windowDidResize:(NSNotification*)notification{[self setInterfaceColumns:interfaceColumns];}
- (void)windowDidResignKey:(NSNotification*)notification{[(MuSceneView*)self.sceneView setHeldDirection:-1];}
- (void)windowWillClose:(NSNotification*)notification{self.sceneView.playing=NO;[((MuSceneView*)self.sceneView).cursorTimer invalidate];[[NSCursor arrowCursor] set];if(self.onClose)self.onClose();}
- (void)windowDidChangeOcclusionState:(NSNotification*)notification{lastFrameTime=0;self.sceneView.playing=assetsPrepared&&(self.window.occlusionState&NSWindowOcclusionStateVisible)!=0;}
- (void)resetCamera:(id)sender{
 [SCNTransaction begin];[SCNTransaction setDisableActions:YES];auto p=self.actorNode.position;cameraTarget=SCNVector3Make(p.x,p.y+.8,p.z);self.cameraNode.position=SCNVector3Make(p.x+5.32,p.y+8.5,p.z+5.32);[self.cameraNode lookAt:cameraTarget];self.sceneView.pointOfView=self.cameraNode;self.sceneView.defaultCameraController.automaticTarget=NO;self.sceneView.defaultCameraController.target=cameraTarget;[SCNTransaction commit];
}
